import{_ as t,o as a,c as i,an as r}from"./chunks/framework.BjXjwTVY.js";const m=JSON.parse('{"title":"Object Lifetimes","description":"","frontmatter":{},"headers":[],"relativePath":"guide/lifetimes.md","filePath":"guide/lifetimes.md","lastUpdated":null}'),l={name:"guide/lifetimes.md"};function o(s,e,d,n,c,f){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="Object-Lifetimes" tabindex="-1">Object Lifetimes <a class="header-anchor" href="#Object-Lifetimes" aria-label="Permalink to &quot;Object Lifetimes {#Object-Lifetimes}&quot;">​</a></h1><p>Objects form a hierarchy: <code>Library</code> ⊃ <code>Context</code> ⊃ <code>Team</code> ⊃ requests and execution engines. A parent is only freed after all its children.</p><ul><li><p>Call <a href="/UCC.jl/stable/api/library#UCC.destroy"><code>UCC.destroy</code></a> when done. If children are still alive, the parent is freed when the last one goes away.</p></li><li><p>Teams are never freed by the GC: destroying a team is collective, so call <code>UCC.destroy(team)</code> on all ranks.</p></li><li><p>Finalizers never call into UCC (they may run on any thread). Garbage-collected objects are queued until you call <a href="/UCC.jl/stable/api/library#UCC.free_deferred"><code>UCC.free_deferred</code></a> at a point where no other thread is using UCC.</p></li><li><p>A nonblocking request that you drop keeps its buffers alive until it completes and <code>free_deferred</code> releases it.</p></li></ul>',3)])])}const u=t(l,[["render",o]]);export{m as __pageData,u as default};
